// Prisma (TypeScript)
import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();

async function crearUsuario() {
  const usuario = await prisma.user.create({
    data: { email: 'juan@example.com', nombre: 'Juan' },
  });
  console.log(usuario);
}
crearUsuario();
